<style>.module-dashboard{padding:12px 0 50px!important}.dash-hero{background:radial-gradient(circle at 85% 20%,rgba(84,200,255,.35),transparent 24%),linear-gradient(135deg,#102a43,#146da8);color:#fff;border-radius:22px;padding:30px;display:flex;justify-content:space-between;align-items:center;box-shadow:0 18px 46px rgba(16,42,67,.22);margin-bottom:18px}.dash-hero h1{font-size:2.25rem;margin:5px 0}.eyebrow{font-size:.72rem;letter-spacing:.14em;font-weight:800;opacity:.72}.metric-grid{margin-top:0!important}.metric-card{border:0!important;border-radius:17px!important;box-shadow:0 9px 25px rgba(25,45,65,.09)!important;border-top:4px solid #2185d0!important}.metric-card.green{border-color:#21ba45!important}.metric-card.orange{border-color:#f2711c!important}.metric-card.violet{border-color:#6435c9!important}.metric-card.teal{border-color:#00b5ad!important}.metric-value{font-size:1.65rem;font-weight:800;color:#18344f;margin:10px 0;overflow-wrap:anywhere}.dash-panel{background:#fff;border:1px solid #e6edf3;border-radius:18px;padding:22px;height:100%;box-shadow:0 8px 26px rgba(20,45,70,.06)}.panel-head{display:flex;justify-content:space-between}.dash-chart{display:grid;gap:15px;margin-top:22px}.chart-row{display:grid;grid-template-columns:150px 1fr 140px;gap:12px;align-items:center}.chart-row>div{height:12px;background:#edf3f7;border-radius:10px;overflow:hidden}.chart-row i{display:block;height:100%;border-radius:10px;background:linear-gradient(90deg,#00b5ad,#2185d0)}.chart-row b{text-align:right}.quick-chat{display:flex;gap:12px;align-items:center;padding:16px;background:#f4fafb;border-radius:13px;margin:20px 0}.quick-chat .icon{font-size:2rem;color:#00a39b}.quick-chat div{flex:1}.quick-chat small{display:block;color:#718096}.workflow{margin-top:14px}.workflow-steps{display:grid;grid-template-columns:repeat(6,1fr);gap:10px;margin-top:18px}.workflow-steps div{position:relative;text-align:center;padding:18px 8px;background:#f7fafc;border-radius:12px}.workflow-steps i{display:block;font-size:1.6rem;color:#2185d0;margin-bottom:7px}.workflow-steps small{position:absolute;top:7px;right:8px;color:#9aa9b7}@media(max-width:800px){.dash-hero{display:block}.dash-hero .button{margin-top:15px}.chart-row{grid-template-columns:100px 1fr}.chart-row b{display:none}.workflow-steps{grid-template-columns:repeat(2,1fr)}}</style><script>document.addEventListener('click',e=>{if(e.target.closest('.dash-refresh'))location.reload()});</script>
